// Generated by AI (UnitTest MCP)
// Tests for the pre-push extension-test selector.
//
// The regression this pins: `scripts/*.test.mjs` (node:test) ran before a push
// and `editors/vscode/scripts/*.test.mjs` (vitest, importing the same modules)
// did not. A rename passed every local check and failed in CI on assertions the
// author had no reason to run — three pull requests were blocked that way at
// once.
//
// The selection is what is tested here, not the vitest run itself: running the
// real suite takes about 18s per file and would make this suite the very thing
// it argues against.
import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";

import { coveringSuite, scrubbedEnvironment, suitesFor } from "./ext-test.mjs";

/** An extension tree advertising the given vitest suites. */
const extensionWith = (suites) => {
  const root = mkdtempSync(join(tmpdir(), "ext-sel-"));
  mkdirSync(join(root, "scripts"), { recursive: true });
  for (const name of suites) {
    writeFileSync(join(root, "scripts", name), "// suite\n");
  }
  return root;
};

test("a changed root module selects the vitest suite that covers it", () => {
  const root = extensionWith(["claim-gate.test.mjs"]);
  try {
    assert.equal(
      coveringSuite("scripts/claim-gate.mjs", root),
      "scripts/claim-gate.test.mjs",
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

/// The cost has to be proportional, or the gate gets switched off. A module with
/// no vitest suite must select nothing rather than fall back to running
/// everything.
test("a module no extension suite covers selects nothing", () => {
  const root = extensionWith(["claim-gate.test.mjs"]);
  try {
    assert.equal(coveringSuite("scripts/adr-index.mjs", root), null);
    assert.deepEqual(suitesFor(["scripts/adr-index.mjs"], root), []);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

/// Editing the node:test suite itself changes no module the vitest suite
/// imports, so it must not drag a 18s run along behind it.
test("editing a node:test suite does not select its vitest twin", () => {
  const root = extensionWith(["claim-gate.test.mjs"]);
  try {
    assert.equal(coveringSuite("scripts/claim-gate.test.mjs", root), null);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("files outside scripts/ select nothing", () => {
  const root = extensionWith(["claim-gate.test.mjs"]);
  try {
    assert.equal(coveringSuite("crates/lodestar-core/src/lib.rs", root), null);
    assert.equal(coveringSuite("docs/SPEC.md", root), null);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

/// Windows hands paths back with backslashes, and a selector that silently
/// matched nothing there would leave half the fleet ungated while reporting
/// success — the failure mode this whole hook exists to remove.
test("a Windows-shaped path selects the same suite", () => {
  const root = extensionWith(["merge-audit.test.mjs"]);
  try {
    assert.equal(
      coveringSuite("scripts\\merge-audit.mjs", root),
      "scripts/merge-audit.test.mjs",
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("one suite is selected once, however many of its modules changed", () => {
  const root = extensionWith(["claim-gate.test.mjs", "merge-audit.test.mjs"]);
  try {
    const suites = suitesFor(
      [
        "scripts/claim-gate.mjs",
        "scripts/claim-gate.mjs",
        "scripts/merge-audit.mjs",
      ],
      root,
    );
    assert.deepEqual(suites, [
      "scripts/claim-gate.test.mjs",
      "scripts/merge-audit.test.mjs",
    ]);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

/// Observed: `canonical-push` sets MINDLEAK_CANONICAL_PUBLISH while running the
/// pre-push hooks, so the suite asserting that a *direct* invocation is refused
/// inherited the flag, saw the direct call allowed, and failed � while passing
/// when run by hand. A runner whose answer depends on who invoked it makes a
/// real guard look broken and sends the author chasing their own tooling.
test("the publisher's own flag never reaches the suite it runs", () => {
  const environment = scrubbedEnvironment({
    MINDLEAK_CANONICAL_PUBLISH: "1",
    PRE_COMMIT_REMOTE_BRANCH: "refs/heads/main",
    PATH: "/usr/bin",
  });

  assert.equal(environment.MINDLEAK_CANONICAL_PUBLISH, undefined);
  assert.equal(environment.PRE_COMMIT_REMOTE_BRANCH, undefined);
  assert.equal(environment.PATH, "/usr/bin", "unrelated variables survive");
});

/// Git hands its hooks GIT_DIR and friends, and they outrank `cwd`. A suite
/// driving git in a temp directory would otherwise read the fixture's files and
/// write to the real repository � which has happened here before.
test("git's hook variables never reach the suite it runs", () => {
  const environment = scrubbedEnvironment({
    GIT_DIR: "/repo/.git",
    GIT_WORK_TREE: "/repo",
    GIT_INDEX_FILE: "/repo/.git/index",
    HOME: "/home/agent",
  });

  for (const leaked of ["GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE"]) {
    assert.equal(environment[leaked], undefined, `${leaked} must not survive`);
  }
  assert.equal(environment.HOME, "/home/agent");
});

test("scrubbing copies rather than mutating the caller's environment", () => {
  const source = { GIT_DIR: "/repo/.git", MINDLEAK_CANONICAL_PUBLISH: "1" };
  scrubbedEnvironment(source);

  assert.equal(
    source.GIT_DIR,
    "/repo/.git",
    "the caller's own env is untouched",
  );
  assert.equal(source.MINDLEAK_CANONICAL_PUBLISH, "1");
});
